'use client';

import React, { useState } from 'react';
import Link from 'next/link';
import { Sparkles, ArrowRight } from 'lucide-react';
import { Product } from '@/types';
import { ProductCard } from '@/components/product/ProductCard';
import { useLanguage } from '@/lib/context/CurrencyLanguageContext';
import { ScrollReveal } from '@/components/common/ScrollReveal';

interface FeaturedProductTabsProps {
  products: Product[];
}

export function FeaturedProductTabs({ products }: FeaturedProductTabsProps) {
  const { t } = useLanguage();
  const [activeTab, setActiveTab] = useState<'featured' | 'trending' | 'new' | 'bestseller'>('featured');

  let filteredProducts: Product[] = [];
  if (activeTab === 'featured') {
    filteredProducts = products.filter((p) => p.is_featured);
  } else if (activeTab === 'trending') {
    filteredProducts = products.filter((p) => p.is_trending);
  } else if (activeTab === 'new') {
    filteredProducts = products.filter((p) => p.is_new);
  } else {
    filteredProducts = [...products].sort((a, b) => b.review_count - a.review_count);
  }

  // Fallback if filter is empty
  if (filteredProducts.length === 0) {
    filteredProducts = products.slice(0, 8);
  }

  const tabs = [
    { id: 'featured', label: t('home.featured_pieces', 'Featured Pieces') },
    { id: 'trending', label: t('home.trending_now', 'Trending Now') },
    { id: 'new', label: t('home.new_arrivals', 'New Arrivals') },
    { id: 'bestseller', label: t('home.client_favorites', 'Client Favorites') },
  ] as const;

  return (
    <section className="py-16 sm:py-24 bg-stone-50/70 dark:bg-[#050505] border-y border-stone-200/60 dark:border-[#1a1a1a] overflow-hidden">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section Header with ScrollReveal */}
        <ScrollReveal direction="up" delay={50}>
          <div className="text-center max-w-2xl mx-auto mb-12 space-y-2.5">
            <div className="inline-flex items-center gap-1.5 px-3.5 py-1.5 bg-stone-200/80 dark:bg-[#111111] border border-transparent dark:border-[#222222] rounded-full text-[11px] font-bold uppercase tracking-widest text-[#c46331] shadow-xs">
              <Sparkles className="w-3.5 h-3.5 animate-pulse" />
              <span>Master Crafted</span>
            </div>
            <h2 className="font-serif text-3xl sm:text-4xl font-bold text-stone-900 dark:text-stone-100 tracking-tight">
              {t('home.selected_works', 'Selected Atelier Works')}
            </h2>
            <p className="text-xs sm:text-sm text-stone-600 dark:text-stone-400 max-w-md mx-auto">
              Handcrafted with enduring elegance, generational durability, and ethical sourcing.
            </p>
          </div>
        </ScrollReveal>

        {/* Filter Tabs with ScrollReveal */}
        <ScrollReveal direction="up" delay={100}>
          <div className="flex items-center justify-center flex-wrap gap-2 sm:gap-3 mb-12">
            {tabs.map((tab) => (
              <button
                key={tab.id}
                onClick={() => setActiveTab(tab.id)}
                className={`px-5 py-2.5 rounded-full text-xs font-bold uppercase tracking-wider transition-all duration-400 ease-[cubic-bezier(0.16,1,0.3,1)] transform active:scale-95 cursor-pointer ${
                  activeTab === tab.id
                    ? 'bg-black dark:bg-white text-white dark:text-black shadow-md scale-105'
                    : 'bg-white dark:bg-[#0a0a0a] text-stone-600 dark:text-stone-400 hover:bg-stone-100 dark:hover:bg-[#151515] hover:text-stone-900 dark:hover:text-stone-100 border border-stone-200 dark:border-[#1a1a1a]'
                }`}
              >
                {tab.label}
              </button>
            ))}
          </div>
        </ScrollReveal>

        {/* Product Cards Grid with Smooth Crossfade Animation */}
        <div
          key={activeTab}
          className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 animate-luxury-fade-up"
        >
          {filteredProducts.slice(0, 8).map((product, idx) => (
            <div
              key={product.id}
              className="animate-luxury-fade-up"
              style={{ animationDelay: `${idx * 70}ms` }}
            >
              <ProductCard product={product} />
            </div>
          ))}
        </div>

        {/* View All CTA with ScrollReveal */}
        <ScrollReveal direction="up" delay={200}>
          <div className="mt-14 text-center">
            <Link
              href="/shop"
              className="btn-luxury-shimmer inline-flex items-center gap-2.5 px-9 py-4 bg-white dark:bg-[#0a0a0a] border border-stone-300 dark:border-[#222222] hover:border-black dark:hover:border-stone-400 text-stone-900 dark:text-stone-200 hover:bg-black dark:hover:bg-white hover:text-white dark:hover:text-black rounded-full text-xs font-bold uppercase tracking-widest shadow-md hover:shadow-xl transition-all duration-400 ease-[cubic-bezier(0.16,1,0.3,1)] transform hover:-translate-y-1 active:scale-95 group"
            >
              <span>Explore Complete Shop ({products.length} Pieces)</span>
              <ArrowRight className="w-4 h-4 transition-transform duration-300 group-hover:translate-x-1.5" />
            </Link>
          </div>
        </ScrollReveal>
      </div>
    </section>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import Link from 'next/link';
import { ChevronLeft, ChevronRight, Sparkles, ArrowRight } from 'lucide-react';
import { HeroBanner } from '@/types';
import { useLanguage } from '@/lib/context/CurrencyLanguageContext';

interface HeroCarouselProps {
  banners: HeroBanner[];
}

export function HeroCarousel({ banners }: HeroCarouselProps) {
  const { t } = useLanguage();
  const activeBanners = (banners || []).filter((b) => b.is_active).sort((a, b) => a.sort_order - b.sort_order);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [isPaused, setIsPaused] = useState(false);

  useEffect(() => {
    if (activeBanners.length <= 1 || isPaused) return;
    const timer = setInterval(() => {
      setCurrentIndex((prev) => (prev + 1) % activeBanners.length);
    }, 6000);
    return () => clearInterval(timer);
  }, [activeBanners.length, isPaused]);

  if (activeBanners.length === 0) return null;

  const current = activeBanners[currentIndex];

  const prevSlide = () => {
    setCurrentIndex((prev) => (prev === 0 ? activeBanners.length - 1 : prev - 1));
  };

  const nextSlide = () => {
    setCurrentIndex((prev) => (prev + 1) % activeBanners.length);
  };

  return (
    <section
      className="relative w-full overflow-hidden bg-black text-white min-h-[500px] sm:min-h-[580px] lg:min-h-[640px] flex items-center smooth-gpu"
      onMouseEnter={() => setIsPaused(true)}
      onMouseLeave={() => setIsPaused(false)}
    >
      {/* Background Image with Dynamic Fade */}
      {activeBanners.map((banner, idx) => (
        <div
          key={banner.id}
          className={`absolute inset-0 transition-opacity duration-1000 ease-in-out ${
            idx === currentIndex ? 'opacity-100 z-0' : 'opacity-0 -z-10 pointer-events-none'
          }`}
        >
          <img
            src={banner.image_url}
            alt={banner.title}
            className="w-full h-full object-cover object-center transform scale-105 transition-transform duration-10000 ease-linear"
          />
          {/* Subtle gradient overlay for luxury readability */}
          <div
            className="absolute inset-0 bg-gradient-to-r from-black/85 via-black/55 to-transparent"
            style={{ backgroundColor: `${banner.background_color}66` }}
          />
        </div>
      ))}

      {/* Hero Content Container */}
      <div className="relative z-10 max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20 w-full">
        <div className="max-w-2xl space-y-5" key={current.id}>
          {current.badge_text && (
            <div className="inline-flex items-center gap-1.5 px-3.5 py-1.5 bg-black/40 backdrop-blur-md border border-white/20 rounded-full text-xs font-bold tracking-widest text-[#f5d480] uppercase shadow-sm animate-luxury-fade-up">
              <Sparkles className="w-3.5 h-3.5 animate-pulse" />
              <span>{t('hero.badge', current.badge_text)}</span>
            </div>
          )}

          <h1 className="font-serif text-3xl sm:text-5xl lg:text-6xl font-bold tracking-tight text-white leading-[1.12] drop-shadow-md animate-luxury-fade-up [animation-delay:180ms]">
            {current.title}
          </h1>

          <p className="text-sm sm:text-base lg:text-lg text-stone-200 font-light leading-relaxed max-w-xl drop-shadow animate-luxury-fade-up [animation-delay:320ms]">
            {current.subtitle}
          </p>

          <div className="pt-3 flex flex-wrap items-center gap-4 animate-luxury-fade-up [animation-delay:460ms]">
            <Link
              href={current.button_url || '/shop'}
              className="btn-luxury-shimmer px-8 py-4 bg-[#c46331] hover:bg-[#d4723c] active:scale-95 text-white text-xs sm:text-sm font-bold uppercase tracking-widest rounded-full shadow-xl hover:shadow-[#c46331]/30 transition-all duration-400 ease-[cubic-bezier(0.16,1,0.3,1)] transform hover:-translate-y-1 flex items-center gap-2.5 group smooth-gpu"
            >
              <span>{t('hero.explore_btn', current.button_text || 'Explore Collection')}</span>
              <ArrowRight className="w-4 h-4 transition-transform duration-300 group-hover:translate-x-1.5" />
            </Link>

            <Link
              href="/shop"
              className="px-7 py-4 bg-black/30 hover:bg-black/50 active:scale-95 backdrop-blur-md border border-white/25 hover:border-white/40 text-white text-xs sm:text-sm font-semibold tracking-wider rounded-full transition-all duration-300 hover:-translate-y-0.5 shadow-sm"
            >
              {t('hero.lookbook_btn', 'View Lookbook')}
            </Link>
          </div>
        </div>
      </div>

      {/* Slide Navigation Arrows */}
      {activeBanners.length > 1 && (
        <>
          <button
            onClick={prevSlide}
            aria-label="Previous Slide"
            className="absolute left-4 top-1/2 -translate-y-1/2 p-3 rounded-full bg-black/30 hover:bg-black/65 active:scale-90 text-white backdrop-blur-md z-20 transition-all duration-300 hover:scale-110 shadow-lg cursor-pointer"
          >
            <ChevronLeft className="w-5 h-5" />
          </button>
          <button
            onClick={nextSlide}
            aria-label="Next Slide"
            className="absolute right-4 top-1/2 -translate-y-1/2 p-3 rounded-full bg-black/30 hover:bg-black/65 active:scale-90 text-white backdrop-blur-md z-20 transition-all duration-300 hover:scale-110 shadow-lg cursor-pointer"
          >
            <ChevronRight className="w-5 h-5" />
          </button>
        </>
      )}

      {/* Slide Indicators / Dots with Progress Fill */}
      {activeBanners.length > 1 && (
        <div className="absolute bottom-6 left-1/2 -translate-x-1/2 flex items-center space-x-2.5 z-20 bg-black/30 backdrop-blur-md px-3 py-1.5 rounded-full border border-white/10">
          {activeBanners.map((_, idx) => (
            <button
              key={idx}
              onClick={() => setCurrentIndex(idx)}
              className={`h-1.5 rounded-full transition-all duration-500 cursor-pointer ${
                currentIndex === idx ? 'w-8 bg-[#c46331] shadow-xs' : 'w-2 bg-white/40 hover:bg-white/80'
              }`}
              aria-label={`Go to slide ${idx + 1}`}
            />
          ))}
        </div>
      )}
    </section>
  );
}

'use client';

import React from 'react';
import Link from 'next/link';
import { ArrowRight, Sparkles } from 'lucide-react';
import { PromoBanner } from '@/types';
import { ScrollReveal } from '@/components/common/ScrollReveal';

interface PromoBannersGridProps {
  banners: PromoBanner[];
}

export function PromoBannersGrid({ banners }: PromoBannersGridProps) {
  const activeBanners = (banners || []).filter((b) => b.is_active).sort((a, b) => a.sort_order - b.sort_order);

  const halfBanners = activeBanners.filter((b) => b.grid_type === 'half');
  const thirdBanners = activeBanners.filter((b) => b.grid_type === 'third');

  return (
    <section className="py-16 sm:py-20 bg-[#fdfbf9] dark:bg-[#000000] overflow-hidden">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 space-y-10">
        {/* 2-Column Spotlight Grid with ScrollReveal */}
        {halfBanners.length > 0 && (
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6 sm:gap-8">
            {halfBanners.map((banner, idx) => (
              <ScrollReveal key={banner.id} direction="up" delay={idx * 120}>
                <Link
                  href={banner.link_url || '/shop'}
                  className="group relative h-[380px] sm:h-[450px] rounded-3xl overflow-hidden shadow-md hover:shadow-luxury-lg dark:hover:shadow-zblack-elevated transition-all duration-600 ease-[cubic-bezier(0.16,1,0.3,1)] transform hover:-translate-y-2 flex flex-col justify-end p-6 sm:p-10 cursor-pointer block smooth-gpu"
                >
                  <img
                    src={banner.image_url}
                    alt={banner.title}
                    className="absolute inset-0 w-full h-full object-cover object-center transition-all duration-700 ease-[cubic-bezier(0.16,1,0.3,1)] group-hover:scale-108"
                    loading="lazy"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent transition-opacity duration-500 group-hover:opacity-95" />

                  <div className="relative z-10 space-y-2.5 text-white max-w-md">
                    {banner.badge_text && (
                      <span className="inline-flex items-center gap-1.5 text-[11px] font-bold uppercase tracking-widest text-[#f5d480] bg-black/50 backdrop-blur-md px-3 py-1 rounded-full border border-white/10 w-max">
                        <Sparkles className="w-3 h-3" /> {banner.badge_text}
                      </span>
                    )}
                    <h3 className="font-serif text-2xl sm:text-3xl font-bold leading-snug text-white tracking-tight">
                      {banner.title}
                    </h3>
                    <p className="text-xs sm:text-sm text-stone-200 line-clamp-2 leading-relaxed">{banner.subtitle}</p>
                    <div className="pt-2">
                      <span className="inline-flex items-center gap-2 text-xs font-bold uppercase tracking-widest text-white border-b-2 border-white/80 pb-0.5 group-hover:border-[#c46331] group-hover:text-[#c46331] transition-colors duration-300">
                        Discover Collection <ArrowRight className="w-4 h-4 transition-transform duration-300 group-hover:translate-x-1.5" />
                      </span>
                    </div>
                  </div>
                </Link>
              </ScrollReveal>
            ))}
          </div>
        )}

        {/* 3-Column Promo Grid with Staggered ScrollReveal */}
        {thirdBanners.length > 0 && (
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            {thirdBanners.map((banner, idx) => (
              <ScrollReveal key={banner.id} direction="up" delay={idx * 100}>
                <Link
                  href={banner.link_url || '/shop'}
                  className="group relative h-[300px] sm:h-[350px] rounded-3xl overflow-hidden shadow-md hover:shadow-luxury-lg dark:hover:shadow-zblack-elevated transition-all duration-600 ease-[cubic-bezier(0.16,1,0.3,1)] transform hover:-translate-y-2 flex flex-col justify-end p-6 cursor-pointer block smooth-gpu"
                >
                  <img
                    src={banner.image_url}
                    alt={banner.title}
                    className="absolute inset-0 w-full h-full object-cover object-center transition-all duration-700 ease-[cubic-bezier(0.16,1,0.3,1)] group-hover:scale-108"
                    loading="lazy"
                  />
                  <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent transition-opacity duration-500 group-hover:opacity-95" />

                  <div className="relative z-10 space-y-2 text-white">
                    {banner.badge_text && (
                      <span className="text-[10px] font-bold uppercase tracking-widest text-[#f5d480] bg-black/40 backdrop-blur-md px-2.5 py-0.5 rounded-full border border-white/10 inline-block w-max">
                        {banner.badge_text}
                      </span>
                    )}
                    <h4 className="font-serif text-lg sm:text-xl font-bold text-white leading-tight">
                      {banner.title}
                    </h4>
                    <p className="text-xs text-stone-300 line-clamp-2 leading-relaxed">{banner.subtitle}</p>
                    <div className="pt-1.5">
                      <span className="text-[11px] font-bold uppercase tracking-wider text-stone-200 group-hover:text-[#c46331] flex items-center gap-1.5 transition-colors duration-300">
                        Shop Now <ArrowRight className="w-3.5 h-3.5 transition-transform duration-300 group-hover:translate-x-1.5" />
                      </span>
                    </div>
                  </div>
                </Link>
              </ScrollReveal>
            ))}
          </div>
        )}
      </div>
    </section>
  );
}

'use client';

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Link from 'next/link';
import { useRouter, usePathname } from 'next/navigation';
import {
  Search,
  ShoppingBag,
  Heart,
  Scale,
  User,
  Menu,
  X,
  ChevronDown,
  Globe,
  Sparkles,
  ShieldCheck,
  LogOut,
  Sliders,
  ExternalLink,
  Sun,
  Moon,
  Package,
  Settings,
  Clock,
  TrendingUp,
  ArrowRight,
  Lightbulb,
  Tag,
} from 'lucide-react';
import { useStore } from '@/lib/context/StoreContext';
import { useCart } from '@/lib/context/CartContext';
import { useWishlist } from '@/lib/context/WishlistContext';
import { useCompare } from '@/lib/context/CompareContext';
import { useCurrency } from '@/lib/context/CurrencyLanguageContext';
import { useAuth } from '@/lib/context/AuthContext';
import { useTheme } from '@/lib/context/ThemeContext';
import { Product } from '@/types';
import {
  fuzzySearchProducts,
  getMatchingCategories,
  getRecentSearches,
  saveRecentSearch,
  clearRecentSearches,
  POPULAR_SEARCH_TERMS,
} from '@/lib/utils/search-matcher';

export function Header() {
  const router = useRouter();
  const pathname = usePathname();
  const { announcement, categories, products, settings } = useStore();
  const { itemCount, openMiniCart } = useCart();
  const { count: wishlistCount } = useWishlist();
  const { count: compareCount } = useCompare();
  const { currency, currencies, setCurrencyCode, formatAmount, language, languages, setLanguage, t, isAutoDetected, detectedCountry } = useCurrency();
  const { user, isAuthenticated, isAdmin, isOrderManager, logout, login } = useAuth();
  const { theme, resolvedTheme, toggleTheme } = useTheme();

  const [isScrolled, setIsScrolled] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [currencyDropdownOpen, setCurrencyDropdownOpen] = useState(false);
  const [userDropdownOpen, setUserDropdownOpen] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchFocused, setSearchFocused] = useState(false);
  const [recentSearches, setRecentSearches] = useState<string[]>([]);
  const [announcementVisible, setAnnouncementVisible] = useState(true);

  const searchRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    setRecentSearches(getRecentSearches());
  }, []);

  useEffect(() => {
    const handleScroll = () => {
      setIsScrolled(window.scrollY > 20);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  // Close dropdowns on outside click
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (searchRef.current && !searchRef.current.contains(event.target as Node)) {
        setSearchFocused(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  // Dynamic fuzzy search suggestions with typo tolerance and scoring
  const fuzzySearchData = useMemo(() => {
    if (!searchQuery.trim()) {
      return { results: [], matchedScores: new Map<string, number>(), didYouMean: undefined };
    }
    return fuzzySearchProducts(products, searchQuery);
  }, [products, searchQuery]);

  // Matching categories & subcategories
  const matchedCategories = useMemo(() => {
    if (!searchQuery.trim()) return [];
    return getMatchingCategories(categories, searchQuery);
  }, [categories, searchQuery]);

  const executeSearch = (query: string) => {
    const clean = query.trim();
    if (clean) {
      const updated = saveRecentSearch(clean);
      setRecentSearches(updated);
      setSearchFocused(false);
      setMobileMenuOpen(false);
      router.push(`/shop?q=${encodeURIComponent(clean)}`);
    }
  };

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    executeSearch(searchQuery);
  };

  return (
    <header className="w-full sticky top-0 z-40 transition-all duration-300">
      {/* Announcement Bar */}
      {announcement?.is_active && announcementVisible && (
        <div
          style={{ backgroundColor: announcement.bg_color || '#1a1816', color: announcement.text_color || '#f5d480' }}
          className="relative text-xs py-2 px-4 text-center font-medium tracking-wide flex items-center justify-center transition-all"
        >
          {announcement.link_url ? (
            <Link href={announcement.link_url} className="hover:underline flex items-center gap-1.5 mx-auto">
              {announcement.text}
            </Link>
          ) : (
            <span className="mx-auto">{announcement.text}</span>
          )}
          <button
            onClick={() => setAnnouncementVisible(false)}
            className="absolute right-3 top-1/2 -translate-y-1/2 opacity-70 hover:opacity-100 p-1"
            aria-label="Dismiss announcement"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        </div>
      )}

      {/* Main Navigation Bar */}
      <nav
        className={`w-full border-b transition-all duration-300 ${
          isScrolled
            ? 'bg-white/95 dark:bg-black/95 backdrop-blur-md border-stone-200/80 dark:border-[#1a1a1a] shadow-sm py-3'
            : 'bg-[#fdfbf9] dark:bg-black border-stone-200/50 dark:border-[#1a1a1a] py-4'
        }`}
      >
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex items-center justify-between gap-3 lg:gap-5">
          {/* Mobile Menu Button & Brand */}
          <div className="flex items-center gap-3 flex-shrink-0">
            <button
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="lg:hidden p-2 rounded-md hover:bg-stone-100 dark:hover:bg-[#151515] text-stone-800 dark:text-stone-200"
              aria-label="Toggle navigation"
            >
              {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>

            <Link href="/" className="flex items-center gap-2 group">
              <span className="font-serif text-2xl sm:text-3xl font-bold tracking-widest text-[#1a1714] dark:text-[#f2ece4] uppercase transition-colors group-hover:text-[#c46331] dark:group-hover:text-amber-400">
                {settings?.general?.storeName || 'Ozeira'}
              </span>
              <span className="hidden sm:inline-block w-1.5 h-1.5 rounded-full bg-[#c46331] dark:bg-amber-400 mb-1"></span>
            </Link>
          </div>

          {/* Desktop Clean Navigation */}
          <div className="hidden lg:flex items-center space-x-5 xl:space-x-7 text-xs font-semibold uppercase tracking-widest text-stone-700 dark:text-stone-300 flex-shrink-0">
            <Link
              href="/shop"
              className={`hover:text-[#c46331] dark:hover:text-amber-400 transition-colors py-1 ${
                pathname === '/shop' ? 'text-[#c46331] dark:text-amber-400 border-b-2 border-[#c46331] dark:border-amber-400' : ''
              }`}
            >
              {t('nav.shop_all', 'Shop All')}
            </Link>
            <Link
              href="/about"
              className={`hover:text-[#c46331] dark:hover:text-amber-400 transition-colors py-1 ${
                pathname === '/about' ? 'text-[#c46331] dark:text-amber-400 border-b-2 border-[#c46331] dark:border-amber-400' : ''
              }`}
            >
              {t('nav.atelier_story', 'Atelier Story')}
