            <p className="text-xs text-stone-600 leading-relaxed">{message}</p>
            <button
              onClick={onClose}
              className="mt-4 px-6 py-2.5 bg-stone-900 text-white rounded-full text-xs font-semibold hover:bg-stone-800"
