  const isCompared = isInCompare(product.id);
  const isOutOfStock = product.total_stock <= 0;

  const handleQuickAdd = (e: React.MouseEvent) => {
    e.preventDefault();
    e.stopPropagation();
    if (isOutOfStock) return;
    const res = addToCart(product);
