'use client';

import React, { createContext, useContext, useState, useEffect } from 'react';
import { UserProfile, UserRole } from '@/types';
import { DataStore } from '@/lib/store/data-store';
import { supabase, isSupabaseConfigured } from '@/lib/supabase/client';

interface AuthContextType {
  user: UserProfile | null;
  isAuthenticated: boolean;
  isAdmin: boolean;
  isOrderManager: boolean;
  login: (email: string, password?: string) => Promise<{ success: boolean; message: string; user?: UserProfile }>;
  signup: (
    email: string,
    password: string,
    fullName: string,
    phone?: string,
    referralCode?: string
  ) => Promise<{ success: boolean; message: string; user?: UserProfile }>;
  logout: () => void;
  updateProfile: (data: Partial<UserProfile>) => Promise<boolean>;
  refreshUser: () => void;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

const AUTH_USER_KEY = 'ozeira_auth_current_user_v1';

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [isLoaded, setIsLoaded] = useState(false);

  useEffect(() => {
    // 1. Initial local restore
    try {
      const stored = localStorage.getItem(AUTH_USER_KEY);
      if (stored) {
        const parsed = JSON.parse(stored);
        const fresh = DataStore.getUserById(parsed.id) || parsed;
        setUser(fresh);
      }
    } catch (e) {
      console.error('Failed to load user', e);
    } finally {
      setIsLoaded(true);
    }

    // 2. Supabase Auth state change listener
    if (isSupabaseConfigured) {
      const { data: authListener } = supabase.auth.onAuthStateChange(async (event, session) => {
        if (session?.user) {
          // Fetch or sync profile from Supabase
          const { data: profile } = await supabase.from('profiles').select('*').eq('id', session.user.id).single();
          if (profile) {
            setUser(profile);
            localStorage.setItem(AUTH_USER_KEY, JSON.stringify(profile));
          }
        }
      });

      return () => {
        authListener?.subscription.unsubscribe();
      };
    }
  }, []);

  const refreshUser = () => {
    if (!user) return;
    const fresh = DataStore.getUserById(user.id);
    if (fresh) {
      setUser(fresh);
      localStorage.setItem(AUTH_USER_KEY, JSON.stringify(fresh));
    }
  };

  const login = async (email: string, password?: string) => {
    // 1. Supabase Auth attempt
    if (isSupabaseConfigured && password) {
      try {
        const { data: authData } = await supabase.auth.signInWithPassword({
          email,
          password,
        });
        if (authData?.user) {
          const { data: profile } = await supabase.from('profiles').select('*').eq('id', authData.user.id).single();
          if (profile) {
            if (profile.is_blocked) {
              await supabase.auth.signOut();
              return { success: false, message: 'This account has been restricted by store administration.' };
            }
            setUser(profile);
            localStorage.setItem(AUTH_USER_KEY, JSON.stringify(profile));
            return { success: true, message: `Welcome back, ${profile.full_name}!`, user: profile };
          }
        }
      } catch (err) {
        console.error('Supabase login error:', err);
      }
    }

    // 2. Demo fallback & offline account check
    const existing = DataStore.getUserByEmail(email);
    if (!existing) {
      return { success: false, message: 'No account found with this email address.' };
    }
    if (existing.is_blocked) {
      return { success: false, message: 'This account has been restricted by store administration.' };
    }
    setUser(existing);
    localStorage.setItem(AUTH_USER_KEY, JSON.stringify(existing));
    return { success: true, message: `Welcome back, ${existing.full_name}!`, user: existing };
  };

  const signup = async (
    email: string,
    password: string,
    fullName: string,
    phone?: string,
    referralCode?: string
  ) => {
    // 1. Supabase Auth registration
    if (isSupabaseConfigured) {
      try {
        const { data: authData } = await supabase.auth.signUp({
          email,
          password,
          options: {
            data: {
              full_name: fullName,
              phone: phone || '',
              role: 'customer',
            },
          },
        });

        if (authData?.user) {
          const newUser = DataStore.createUser(
            {
              id: authData.user.id,
              email,
              full_name: fullName,
              phone,
              role: 'customer',
            },
            referralCode
          );
          setUser(newUser);
          localStorage.setItem(AUTH_USER_KEY, JSON.stringify(newUser));
          return {
            success: true,
            message: 'Account created successfully! 250 welcome points credited to your wallet.',
            user: newUser,
          };
        }
      } catch (err) {
        console.error('Supabase signup error:', err);
      }
    }

    // 2. Offline / Local fallback registration
    const existing = DataStore.getUserByEmail(email);
    if (existing) {
      return { success: false, message: 'An account with this email already exists. Please login.' };
    }
    const newUser = DataStore.createUser(
      {
        email,
        full_name: fullName,
        phone,
        role: 'customer',
      },
      referralCode
    );
    setUser(newUser);
    localStorage.setItem(AUTH_USER_KEY, JSON.stringify(newUser));
    return {
      success: true,
      message: 'Account created successfully! 250 welcome points credited to your wallet.',
      user: newUser,
    };
  };

  const logout = () => {
    if (isSupabaseConfigured) {
      supabase.auth.signOut();
    }
    setUser(null);
    localStorage.removeItem(AUTH_USER_KEY);
  };

  const updateProfile = async (data: Partial<UserProfile>) => {
    if (!user) return false;
    const updated = DataStore.saveUser({ ...user, ...data });
    setUser(updated);
    localStorage.setItem(AUTH_USER_KEY, JSON.stringify(updated));
    return true;
  };

  const isAdmin = user?.role === 'admin';
  const isOrderManager = user?.role === 'admin' || user?.role === 'order_manager';

  return (
    <AuthContext.Provider
      value={{
        user,
        isAuthenticated: !!user,
        isAdmin,
        isOrderManager,
        login,
        signup,
        logout,
        updateProfile,
        refreshUser,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export function useAuth() {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
}

'use client';

import React, { createContext, useContext, useState, useEffect } from 'react';
import { CartItem, Product, ProductVariant, Coupon } from '@/types';
import { DataStore } from '@/lib/store/data-store';
import { INITIAL_SETTINGS } from '@/lib/data/initial-data';
import { AnalyticsService } from '@/lib/services/analytics';

export interface CartToastItem {
  product: Product;
  variant?: ProductVariant;
  quantity: number;
}

interface CartContextType {
  items: CartItem[];
  itemCount: number;
  subtotal: number;
  discountAmount: number;
  shippingFee: number;
  codFee: number;
  taxAmount: number;
  totalAmount: number;
  freeShippingThreshold: number;
  amountNeededForFreeShipping: number;
  isMiniCartOpen: boolean;
  appliedCoupon: Coupon | null;
  couponDiscount: number;
  couponMessage: string;
  loyaltyPointsToUse: number;
  loyaltyDiscount: number;
  maxLoyaltyPointsAllowed: number;
  toastItem: CartToastItem | null;
  dismissToast: () => void;
  openMiniCart: () => void;
  closeMiniCart: () => void;
  toggleMiniCart: () => void;
  addToCart: (product: Product, variantId?: string, quantity?: number) => { success: boolean; message: string };
  updateQuantity: (itemId: string, quantity: number) => void;
  removeItem: (itemId: string) => void;
  clearCart: () => void;
  applyCoupon: (code: string) => { success: boolean; message: string };
  removeCoupon: () => void;
  setLoyaltyPointsToUse: (points: number) => void;
  shippingMethod: 'standard' | 'express';
  setShippingMethod: (method: 'standard' | 'express') => void;
  paymentMethod: 'razorpay' | 'cod';
  setPaymentMethod: (method: 'razorpay' | 'cod') => void;
}

const CartContext = createContext<CartContextType | undefined>(undefined);

const CART_STORAGE_KEY = 'ozeira_cart_items_v1';
const COUPON_STORAGE_KEY = 'ozeira_applied_coupon_v1';

export function CartProvider({ children }: { children: React.ReactNode }) {
  const [items, setItems] = useState<CartItem[]>([]);
  const [isMiniCartOpen, setIsMiniCartOpen] = useState(false);
  const [toastItem, setToastItem] = useState<CartToastItem | null>(null);
  const [appliedCoupon, setAppliedCoupon] = useState<Coupon | null>(null);
  const [couponDiscount, setCouponDiscount] = useState(0);
  const [couponMessage, setCouponMessage] = useState('');
  const [loyaltyPointsToUse, setLoyaltyPointsToUseState] = useState(0);
  const [shippingMethod, setShippingMethod] = useState<'standard' | 'express'>('standard');
  const [paymentMethod, setPaymentMethod] = useState<'razorpay' | 'cod'>('razorpay');

  const settings = DataStore.getSettings() || INITIAL_SETTINGS;

  useEffect(() => {
    try {
      const stored = localStorage.getItem(CART_STORAGE_KEY);
      if (stored) {
        setItems(JSON.parse(stored));
      }

      const storedCoupon = localStorage.getItem(COUPON_STORAGE_KEY);
      if (storedCoupon) {
        const coupon = JSON.parse(storedCoupon);
        setAppliedCoupon(coupon);
      }
    } catch (e) {
      console.error('Failed to load cart from storage', e);
    }
  }, []);

  const saveItems = (newItems: CartItem[]) => {
    setItems(newItems);
    try {
      localStorage.setItem(CART_STORAGE_KEY, JSON.stringify(newItems));
    } catch (e) {
      console.error('Failed to save cart to storage', e);
    }
  };

  const openMiniCart = () => setIsMiniCartOpen(true);
  const closeMiniCart = () => setIsMiniCartOpen(false);
  const toggleMiniCart = () => setIsMiniCartOpen((prev) => !prev);
  const dismissToast = () => setToastItem(null);

  const addToCart = (product: Product, variantId?: string, quantity: number = 1): { success: boolean; message: string } => {
    let variant: ProductVariant | undefined;
    if (variantId) {
      variant = product.variants?.find((v) => v.id === variantId);
    } else if (product.variants?.length > 0) {
      variant = product.variants[0];
    }

    const availableStock = variant ? variant.stock_quantity : product.total_stock;
    if (availableStock <= 0) {
      return { success: false, message: 'This item is currently out of stock.' };
    }

    const cartItemId = `${product.id}-${variant?.id || 'default'}`;
    const existingIndex = items.findIndex((i) => i.id === cartItemId);

    let updated: CartItem[];
    if (existingIndex >= 0) {
      const currentQty = items[existingIndex].quantity;
      const newQty = currentQty + quantity;
      if (newQty > availableStock) {
        return {
          success: false,
          message: `Only ${availableStock} units available in stock.`,
        };
      }
      updated = [...items];
      updated[existingIndex].quantity = newQty;
    } else {
      if (quantity > availableStock) {
        return {
          success: false,
          message: `Only ${availableStock} units available in stock.`,
        };
      }
      const newItem: CartItem = {
        id: cartItemId,
        productId: product.id,
        product,
        variantId: variant?.id,
        variant,
        quantity,
      };
      updated = [newItem, ...items];
    }

    saveItems(updated);

    // Trigger Toast Notification with Auto-Dismiss
    setToastItem({ product, variant, quantity });
    setTimeout(() => {
      setToastItem((current) => (current?.product.id === product.id ? null : current));
    }, 4500);

    // E-Commerce Analytics Tracking
    try {
      AnalyticsService.trackAddToCart({
        id: product.id,
        name: product.title,
        price: (product.sale_price ?? product.base_price) + (variant?.additional_price || 0),
        quantity: quantity,
        category: product.category_name || product.brand,
      });
    } catch {
      // safe fallback
    }

    return { success: true, message: `Added "${product.title}" to cart!` };
  };

  const updateQuantity = (itemId: string, quantity: number) => {
    if (quantity <= 0) {
      removeItem(itemId);
      return;
    }
    const updated = items.map((item) => {
      if (item.id === itemId) {
        const availableStock = item.variant ? item.variant.stock_quantity : item.product.total_stock;
        return {
          ...item,
          quantity: Math.min(quantity, Math.max(1, availableStock)),
        };
      }
      return item;
    });
    saveItems(updated);
  };

  const removeItem = (itemId: string) => {
    const updated = items.filter((i) => i.id !== itemId);
    saveItems(updated);
  };

  const clearCart = () => {
    saveItems([]);
    removeCoupon();
    setLoyaltyPointsToUseState(0);
  };

  // Pricing calculations
  const itemCount = items.reduce((sum, item) => sum + item.quantity, 0);

  const subtotal = items.reduce((sum, item) => {
    const basePrice = item.product.sale_price ?? item.product.base_price;
    const variantExtra = item.variant?.additional_price ?? 0;
    return sum + (basePrice + variantExtra) * item.quantity;
  }, 0);

  const freeShippingThreshold = settings?.shipping?.freeShippingThreshold ?? 2500;
  const standardShippingFee = settings?.shipping?.standardShippingFee ?? 150;
  const expressShippingFee = settings?.shipping?.expressShippingFee ?? 300;
  const codHandlingFee = settings?.cod?.handlingFee ?? 50;

  const isFreeShipping = subtotal >= freeShippingThreshold;
  const amountNeededForFreeShipping = Math.max(0, freeShippingThreshold - subtotal);

  let shippingFee = 0;
  if (items.length > 0) {
    if (shippingMethod === 'express') {
      shippingFee = expressShippingFee;
    } else {
      shippingFee = isFreeShipping ? 0 : standardShippingFee;
    }
  }

  const codFee = paymentMethod === 'cod' && items.length > 0 ? codHandlingFee : 0;

  // Coupon handling
  const applyCoupon = (code: string): { success: boolean; message: string } => {
    const res = DataStore.validateCoupon(code, subtotal);
    if (!res.valid || !res.coupon) {
      return { success: false, message: res.message };
    }

    setAppliedCoupon(res.coupon);
    setCouponDiscount(res.discount);
    setCouponMessage(res.message);

    try {
      localStorage.setItem(COUPON_STORAGE_KEY, JSON.stringify(res.coupon));
    } catch (e) {
      console.error('Failed to save coupon to storage', e);
    }

    return { success: true, message: res.message };
  };

  const removeCoupon = () => {
    setAppliedCoupon(null);
    setCouponDiscount(0);
    setCouponMessage('');
    try {
      localStorage.removeItem(COUPON_STORAGE_KEY);
    } catch (e) {
      console.error('Failed to remove coupon from storage', e);
    }
  };

  // Recalculate coupon discount when subtotal changes
  useEffect(() => {
    if (appliedCoupon) {
      if (subtotal < appliedCoupon.min_order_amount) {
        removeCoupon();
      } else {
        let discount = 0;
        if (appliedCoupon.discount_type === 'percentage') {
          discount = (subtotal * appliedCoupon.discount_value) / 100;
          if (appliedCoupon.max_discount_amount) {
            discount = Math.min(discount, appliedCoupon.max_discount_amount);
          }
        } else {
          discount = Math.min(appliedCoupon.discount_value, subtotal);
        }
        setCouponDiscount(discount);
      }
    }
  }, [subtotal, appliedCoupon]);

  // Loyalty calculations: 100 points = ₹10 (1 point = ₹0.10)
  const POINT_VALUE_INR = 0.1;
  const MAX_LOYALTY_DISCOUNT_PERCENT = 0.3; // Max 30% of subtotal can be paid with points
  const maxLoyaltyDiscount = subtotal * MAX_LOYALTY_DISCOUNT_PERCENT;
  const maxLoyaltyPointsAllowed = Math.floor(maxLoyaltyDiscount / POINT_VALUE_INR);

  const effectiveLoyaltyPoints = Math.min(loyaltyPointsToUse, maxLoyaltyPointsAllowed);
  const loyaltyDiscount = effectiveLoyaltyPoints * POINT_VALUE_INR;

  const setLoyaltyPointsToUse = (points: number) => {
    setLoyaltyPointsToUseState(Math.max(0, Math.min(points, maxLoyaltyPointsAllowed)));
  };

  // Tax calculation (GST 12% standard on jewelry / luxury accessories)
  const gstRate = 0.12;
  const discountedSubtotal = Math.max(0, subtotal - couponDiscount - loyaltyDiscount);
  const taxAmount = Math.round(discountedSubtotal * gstRate);

  const totalAmount = Math.max(0, discountedSubtotal + shippingFee + codFee + taxAmount);

  return (
    <CartContext.Provider
      value={{
        items,
        itemCount,
        subtotal,
        discountAmount: couponDiscount + loyaltyDiscount,
        shippingFee,
        codFee,
        taxAmount,
        totalAmount,
        freeShippingThreshold,
        amountNeededForFreeShipping,
        isMiniCartOpen,
        appliedCoupon,
        couponDiscount,
        couponMessage,
        loyaltyPointsToUse: effectiveLoyaltyPoints,
        loyaltyDiscount,
        maxLoyaltyPointsAllowed,
        toastItem,
        dismissToast,
        openMiniCart,
        closeMiniCart,
        toggleMiniCart,
        addToCart,
        updateQuantity,
        removeItem,
        clearCart,
        applyCoupon,
        removeCoupon,
        setLoyaltyPointsToUse,
        shippingMethod,
        setShippingMethod,
        paymentMethod,
        setPaymentMethod,
      }}
    >
      {children}
    </CartContext.Provider>
  );
}

export function useCart() {
  const context = useContext(CartContext);
  if (!context) {
    throw new Error('useCart must be used within a CartProvider');
  }
  return context;
}

'use client';

import React, { createContext, useContext, useState, useEffect } from 'react';
import { Product } from '@/types';
import { DataStore } from '@/lib/store/data-store';

interface CompareContextType {
  compareIds: string[];
  compareProducts: Product[];
  addToCompare: (productId: string) => { success: boolean; message: string };
  removeFromCompare: (productId: string) => void;
  isInCompare: (productId: string) => boolean;
  clearCompare: () => void;
  count: number;
}

const CompareContext = createContext<CompareContextType | undefined>(undefined);

const COMPARE_KEY = 'ozeira_compare_v1';
const MAX_COMPARE_ITEMS = 4;

export function CompareProvider({ children }: { children: React.ReactNode }) {
  const [compareIds, setCompareIds] = useState<string[]>([]);
  const [products, setProducts] = useState<Product[]>([]);

  useEffect(() => {
    try {
      const stored = localStorage.getItem(COMPARE_KEY);
      if (stored) {
        setCompareIds(JSON.parse(stored));
      }
      setProducts(DataStore.getProducts());
    } catch (e) {
      console.error('Failed to load compare items', e);
    }
  }, []);

  const addToCompare = (productId: string): { success: boolean; message: string } => {
    if (compareIds.includes(productId)) {
      removeFromCompare(productId);
      return { success: true, message: 'Removed from product comparison.' };
    }
    if (compareIds.length >= MAX_COMPARE_ITEMS) {
      return { success: false, message: `You can compare up to ${MAX_COMPARE_ITEMS} products at once.` };
    }
    const updated = [...compareIds, productId];
    setCompareIds(updated);
    try {
      localStorage.setItem(COMPARE_KEY, JSON.stringify(updated));
    } catch (e) {
      console.error('Error saving compare items', e);
    }
    return { success: true, message: 'Added to product comparison.' };
  };

  const removeFromCompare = (productId: string) => {
    const updated = compareIds.filter((id) => id !== productId);
    setCompareIds(updated);
    try {
      localStorage.setItem(COMPARE_KEY, JSON.stringify(updated));
    } catch (e) {
      console.error('Error saving compare items', e);
    }
  };

  const isInCompare = (productId: string) => compareIds.includes(productId);

  const clearCompare = () => {
    setCompareIds([]);
    localStorage.removeItem(COMPARE_KEY);
  };

  const compareProducts = products.filter((p) => compareIds.includes(p.id));

  return (
    <CompareContext.Provider
      value={{
        compareIds,
        compareProducts,
        addToCompare,
        removeFromCompare,
        isInCompare,
        clearCompare,
        count: compareIds.length,
      }}
    >
      {children}
    </CompareContext.Provider>
  );
}

export function useCompare() {
  const context = useContext(CompareContext);
  if (!context) {
    throw new Error('useCompare must be used within a CompareProvider');
  }
  return context;
}

'use client';

import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { CurrencyConfig } from '@/types';
import { INITIAL_SETTINGS } from '@/lib/data/initial-data';
import { DataStore } from '@/lib/store/data-store';
import { formatPrice } from '@/lib/utils';
import { getTranslation, SupportedLanguage } from '@/lib/i18n/translations';

interface CurrencyLanguageContextType {
  currency: CurrencyConfig;
  currencies: CurrencyConfig[];
  setCurrencyCode: (code: string) => void;
  formatAmount: (amountInINR: number) => string;
  formatPriceValue: (amountInINR: number) => string;
  language: string;
  languages: { code: string; name: string; nativeName: string }[];
  setLanguage: (lang: string) => void;
  t: (key: string, fallback?: string) => string;
  isAutoDetected: boolean;
  detectedCountry?: string;
}

const CurrencyLanguageContext = createContext<CurrencyLanguageContextType | undefined>(undefined);

const CURRENCY_STORAGE_KEY = 'ozeira_currency_v1';
const USER_SET_CURRENCY_KEY = 'ozeira_user_selected_currency_v1';
const LANGUAGE_STORAGE_KEY = 'ozeira_language_v1';

export const SUPPORTED_LANGUAGES = [
  { code: 'en', name: 'English', nativeName: 'English' },
  { code: 'hi', name: 'Hindi', nativeName: 'हिन्दी' },
  { code: 'fr', name: 'French', nativeName: 'Français' },
  { code: 'es', name: 'Spanish', nativeName: 'Español' },
  { code: 'ar', name: 'Arabic', nativeName: 'العربية' },
];

// Country Code to Supported Currency Mapping
const COUNTRY_TO_CURRENCY: Record<string, string> = {
  IN: 'INR',
  US: 'USD',
  CA: 'USD',
  AU: 'USD',
  NZ: 'USD',
  SG: 'USD',
  GB: 'GBP',
  UK: 'GBP',
  AE: 'AED',
  SA: 'AED',
  QA: 'AED',
  KW: 'AED',
  BH: 'AED',
  OM: 'AED',
  FR: 'EUR',
  DE: 'EUR',
  IT: 'EUR',
  ES: 'EUR',
  NL: 'EUR',
  BE: 'EUR',
  AT: 'EUR',
  PT: 'EUR',
  IE: 'EUR',
  GR: 'EUR',
  FI: 'EUR',
};

function detectCurrencyFromTimezone(): { currency: string; countryCode: string } {
  try {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || '';
    if (tz.includes('Kolkata') || tz.includes('Calcutta') || tz.includes('India')) {
      return { currency: 'INR', countryCode: 'IN' };
    }
    if (tz.startsWith('America/')) {
      return { currency: 'USD', countryCode: 'US' };
    }
    if (tz.includes('London')) {
      return { currency: 'GBP', countryCode: 'GB' };
    }
    if (tz.includes('Dubai') || tz.includes('Riyadh') || tz.includes('Qatar')) {
      return { currency: 'AED', countryCode: 'AE' };
    }
    if (tz.startsWith('Europe/')) {
      return { currency: 'EUR', countryCode: 'FR' };
    }
  } catch {}
  return { currency: 'INR', countryCode: 'IN' };
}

export function CurrencyLanguageProvider({ children }: { children: React.ReactNode }) {
  const [currencies, setCurrencies] = useState<CurrencyConfig[]>(INITIAL_SETTINGS.currencies);
  const [currency, setCurrency] = useState<CurrencyConfig>(INITIAL_SETTINGS.currencies[0]);
  const [language, setLanguageState] = useState<string>('en');
  const [isAutoDetected, setIsAutoDetected] = useState(false);
  const [detectedCountry, setDetectedCountry] = useState<string | undefined>(undefined);

  // 1. Initialize Currency & Detect Visitor Geolocation
  useEffect(() => {
    try {
      const settings = DataStore.getSettings();
      const activeCurrencies = (settings?.currencies?.length ? settings.currencies : INITIAL_SETTINGS.currencies).filter((c) => c.isEnabled);
      setCurrencies(activeCurrencies);

      const hasUserSelected = localStorage.getItem(USER_SET_CURRENCY_KEY) === 'true';
      const storedCurrency = localStorage.getItem(CURRENCY_STORAGE_KEY);

      if (hasUserSelected && storedCurrency) {
        const match = activeCurrencies.find((c) => c.code === storedCurrency);
        if (match) {
          setCurrency(match);
          return;
        }
      }

      // Auto-detect visitor's country & currency based on IP and timezone
      const tzInfo = detectCurrencyFromTimezone();
      const fallbackCode = tzInfo.currency;
      setDetectedCountry(tzInfo.countryCode);

      const tzMatch = activeCurrencies.find((c) => c.code === fallbackCode);
      if (tzMatch) {
        setCurrency(tzMatch);
        setIsAutoDetected(true);
      }

      // Attempt async IP geolocation detection
      fetch('https://ipapi.co/json/')
        .then((res) => res.json())
        .then((data) => {
          if (data && data.country_code) {
            setDetectedCountry(data.country_code);
            const mappedCurrency = COUNTRY_TO_CURRENCY[data.country_code] || data.currency || fallbackCode;
            const geoMatch = activeCurrencies.find((c) => c.code === mappedCurrency);
            if (geoMatch && !localStorage.getItem(USER_SET_CURRENCY_KEY)) {
              setCurrency(geoMatch);
              localStorage.setItem(CURRENCY_STORAGE_KEY, geoMatch.code);
              setIsAutoDetected(true);
            }
          }
        })
        .catch(() => {
          // Keep timezone fallback
        });
    } catch (e) {
      console.error('Error loading currency settings', e);
    }
  }, []);

  // 2. Initialize Language & Setup Google Translate Widget
  useEffect(() => {
    try {
      const storedLang = localStorage.getItem(LANGUAGE_STORAGE_KEY) || 'en';
      setLanguageState(storedLang);
      document.documentElement.lang = storedLang;
      document.documentElement.dir = storedLang === 'ar' ? 'rtl' : 'ltr';

      // If English (default), ensure all translation cookies are wiped
      if (storedLang === 'en' && typeof document !== 'undefined') {
        const domain = window.location.hostname;
        document.cookie = `googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/; domain=${domain};`;
        document.cookie = `googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;`;
        document.cookie = `googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC;`;
      }

      // Setup Google Translate hidden element and script
      if (typeof window !== 'undefined') {
        if (!document.getElementById('google_translate_element')) {
          const div = document.createElement('div');
          div.id = 'google_translate_element';
          div.style.display = 'none';
          document.body.appendChild(div);
        }

        (window as any).googleTranslateElementInit = () => {
          try {
            new (window as any).google.translate.TranslateElement(
              {
                pageLanguage: 'en',
                includedLanguages: 'en,hi,fr,es,ar',
                autoDisplay: false,
                layout: (window as any).google.translate.TranslateElement.InlineLayout.SIMPLE,
              },
              'google_translate_element'
            );
          } catch (e) {}
        };

        if (!document.getElementById('google-translate-script')) {
          const script = document.createElement('script');
          script.id = 'google-translate-script';
          script.src = 'https://translate.google.com/translate_a/element.js?cb=googleTranslateElementInit';
          script.async = true;
          document.body.appendChild(script);
        }
      }
    } catch (e) {
      console.error('Error loading language settings', e);
    }
  }, []);

  const setCurrencyCode = (code: string) => {
    const found = currencies.find((c) => c.code === code);
    if (found) {
      setCurrency(found);
      localStorage.setItem(CURRENCY_STORAGE_KEY, code);
      localStorage.setItem(USER_SET_CURRENCY_KEY, 'true'); // Flag user explicit selection
      setIsAutoDetected(false);
    }
  };

  const setLanguage = (lang: string) => {
    setLanguageState(lang);
    localStorage.setItem(LANGUAGE_STORAGE_KEY, lang);

    if (typeof document !== 'undefined') {
      document.documentElement.lang = lang;
      document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';

      const domain = window.location.hostname;
      if (lang === 'en') {
        document.cookie = `googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/; domain=${domain};`;
        document.cookie = `googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;`;
        document.cookie = `googtrans=; expires=Thu, 01 Jan 1970 00:00:00 UTC;`;

        const selectElem = document.querySelector('.goog-te-combo') as HTMLSelectElement;
        if (selectElem) {
          selectElem.value = 'en';
          selectElem.dispatchEvent(new Event('change'));
        }
        window.location.reload();
        return;
      }

      const transVal = `/en/${lang}`;
      document.cookie = `googtrans=${transVal}; path=/; domain=${domain};`;
      document.cookie = `googtrans=${transVal}; path=/;`;

      // Trigger Google Translate dropdown if loaded
      const selectElem = document.querySelector('.goog-te-combo') as HTMLSelectElement;
      if (selectElem) {
        selectElem.value = lang;
        selectElem.dispatchEvent(new Event('change'));
      } else {
        setTimeout(() => {
          window.location.reload();
        }, 150);
      }
    }
  };

  const t = useCallback(
    (key: string, fallback?: string): string => {
      return getTranslation(language as SupportedLanguage, key, fallback);
    },
    [language]
  );

  const formatAmount = (amountInINR: number): string => {
    return formatPrice(amountInINR, currency.code, currency.symbol, currency.rateAgainstINR);
  };

  return (
    <CurrencyLanguageContext.Provider
      value={{
        currency,
        currencies,
        setCurrencyCode,
        formatAmount,
        formatPriceValue: formatAmount,
        language,
        languages: SUPPORTED_LANGUAGES,
        setLanguage,
        t,
        isAutoDetected,
        detectedCountry,
      }}
    >
      {children}
    </CurrencyLanguageContext.Provider>
  );
}

export function useCurrency() {
  const context = useContext(CurrencyLanguageContext);
  if (!context) {
    throw new Error('useCurrency must be used within a CurrencyLanguageProvider');
  }
  return context;
}

export function useLanguage() {
  const context = useContext(CurrencyLanguageContext);
  if (!context) {
    throw new Error('useLanguage must be used within a CurrencyLanguageProvider');
  }
  return {
    language: context.language,
    languages: context.languages,
    setLanguage: context.setLanguage,
    t: context.t,
  };
}
